DO $p3c_do$
DECLARE
  v_data jsonb := $p3c_json${"standard":{"code":"DWA-M-102-4","title_de":"Grundsätze zur Bewirtschaftung und Behandlung von Regenwetterabflüssen zur Einleitung in Oberflächengewässer - Teil 4: Wasserhaushaltsbilanz für die Bewirtschaftung des Niederschlagswassers","title_en":"Principles for the management and treatment of stormwater runoff for discharge into surface waters - Part 4: Water balance for the management of stormwater","version":"März 2022"},"worksheets":[{"code":"M104-01","title_de":"Projektregistrierung","title_en":"Project Registration","phase":1,"archetype":"registration","order_index":1,"description":"Project metadata, location, cadastral data, regulatory framework. Triggers the 800 m² Relevanzgrenze gate."},{"code":"M104-02","title_de":"Bilanzgebietsdefinition","title_en":"Balance Area Definition","phase":1,"archetype":"data_collection","order_index":2,"description":"Defines A_E,k (catchment), A_E,k,b (impervious), A_E,k,nb (pervious). Subdivides connected vs disconnected impervious surfaces."},{"code":"M104-03","title_de":"Datenquellenwahl","title_en":"Data Source Selection","phase":1,"archetype":"data_collection","order_index":3,"description":"Chooses between WaSiG, water-balance models, GWneu, or HAD as the basis for reference-state determination."},{"code":"M104-04","title_de":"Niederschlagsdaten","title_en":"Precipitation Data","phase":2,"archetype":"data_collection","order_index":4,"description":"Captures mean annual precipitation P and corrected P_korr. Validates against HAD raster data per §5.2.5."},{"code":"M104-05","title_de":"Verdunstungsdaten (Evapotranspiration)","title_en":"Evapotranspiration Data","phase":2,"archetype":"data_collection","order_index":5,"description":"Captures potential evapotranspiration ET_p and group (1-6 per Tab. C.1). Sources: HAD, DWD, BAGLUVA."},{"code":"M104-06","title_de":"Klimadatenzusammenfassung","title_en":"Climate Data Summary","phase":2,"archetype":"summary","order_index":6,"description":"Consolidates P, P_korr, ET_p, ET_p group for downstream worksheets."},{"code":"M104-07","title_de":"Berechnung des Referenzzustands","title_en":"Reference State Calculation","phase":3,"archetype":"calculation","order_index":7,"description":"Computes unbebauter Zustand water balance (R_D, GWN, ET_a) per §5.2 using WaSiG/GWneu/HAD/models."},{"code":"M104-08","title_de":"Boden- und Geländedaten","title_en":"Soil and Terrain Data","phase":3,"archetype":"data_collection","order_index":8,"description":"Captures soil group (1-5 per Tab. C.2), k_f, slope class, groundwater depth. Drives r-value lookup in Tab. C.7."},{"code":"M104-09","title_de":"Landnutzungsklassifikation","title_en":"Land Use Classification","phase":3,"archetype":"data_collection","order_index":9,"description":"CORINE Land Cover or BAGLUVA Landnutzungseinheit selection (Grünland, Ackerland, Laubwald, Nadelwald, Vegetationslose Fläche)."},{"code":"M104-10","title_de":"Wasserbilanzvergleich und Zielvorgaben","title_en":"Water Balance Comparison and Targets","phase":3,"archetype":"calculation","order_index":10,"description":"Sets target deviations (≤ 5-10 percentage points per §5.3.3) for a, g, v vs reference state."},{"code":"M104-11","title_de":"Inventar befestigter Flächen","title_en":"Sealed Surface Inventory","phase":4,"archetype":"data_collection","order_index":11,"description":"Inventories all impervious surfaces by type and connection status. Distinguishes A_E,k,b,a (connected) and A_E,k,b,na (disconnected)."},{"code":"M104-12","title_de":"Dachflächen — Parameter","title_en":"Roof Surface Parameters","phase":4,"archetype":"data_collection","order_index":12,"description":"Roof surface parameters: storage height Sp, slope, material, substrate h_S for green roofs."},{"code":"M104-13","title_de":"Verkehrs- und Wegflächen — Parameter","title_en":"Traffic and Paved Surface Parameters","phase":4,"archetype":"data_collection","order_index":13,"description":"Paved surface parameters: Sp, joint fraction f_Fu, k_f, h_D for permeable pavements."},{"code":"M104-14","title_de":"Vegetations-/Durchlässige Flächen — Parameter","title_en":"Vegetation/Pervious Surface Parameters","phase":4,"archetype":"data_collection","order_index":14,"description":"Pervious surface parameters: soil group, GW depth, location factor f_L, irrigation factor f_W."},{"code":"M104-15","title_de":"Flächeninventar — Zusammenfassung","title_en":"Surface Inventory Summary","phase":4,"archetype":"summary","order_index":15,"description":"Consolidates all surface areas across M104-11..14. Verifies sum balance to A_E,k."},{"code":"M104-16","title_de":"Aufteilungswerte Dachflächen","title_en":"Roof Surface Coefficient Calculations","phase":5,"archetype":"calculation","order_index":16,"description":"Computes a_F, g_F, v_F per roof type using regression equations A.2-A.5."},{"code":"M104-17","title_de":"Aufteilungswerte Verkehrsflächen","title_en":"Traffic & Paved Surface Coefficient Calculations","phase":5,"archetype":"calculation","order_index":17,"description":"Computes coefficients for Asphalt/Beton/dichte Fugen per regression A.3."},{"code":"M104-18","title_de":"Aufteilungswerte teildurchlässige Beläge","title_en":"Permeable Pavement Coefficient Calculations","phase":5,"archetype":"calculation","order_index":18,"description":"Computes coefficients for permeable pavements per Anhang A.6 to A.10."},{"code":"M104-19","title_de":"Aufteilungswerte Gründach/Einstaudach","title_en":"Green Roof & Retention Roof Calculations","phase":5,"archetype":"calculation","order_index":19,"description":"Computes coefficients for green roofs and retention roofs."},{"code":"M104-20","title_de":"Aufteilungswerte Vegetationsflächen","title_en":"Vegetation Surface Coefficient Calculations","phase":5,"archetype":"calculation","order_index":20,"description":"Computes a_F, g_F, v_F for non-sealed vegetated surfaces via Anhang C method (BAGLUVA simplified)."},{"code":"M104-21","title_de":"Flächenkoeffizienten — Zusammenfassung","title_en":"Surface Coefficient Summary","phase":5,"archetype":"summary","order_index":21,"description":"Consolidates surface-level a_F, g_F, v_F values. Verifies Kontrollbedingung a_F + g_F + v_F = 1."},{"code":"M104-22","title_de":"Anlagentyp-Wahl","title_en":"Facility Type Selection","phase":6,"archetype":"calculation","order_index":22,"description":"Selects facility types per Tab. B.1."},{"code":"M104-23","title_de":"Aufteilungswerte Flächenversickerung","title_en":"Surface Infiltration Coefficients","phase":6,"archetype":"calculation","order_index":23,"description":"Computes a_A, g_A, v_A for Flächenversickerung."},{"code":"M104-24","title_de":"Aufteilungswerte Versickerungsmulden","title_en":"Infiltration Swale Coefficients","phase":6,"archetype":"calculation","order_index":24,"description":"Computes coefficients for Versickerungsmulden per Anhang B.3."},{"code":"M104-25","title_de":"Aufteilungswerte Mulden-Rigolen-Elemente","title_en":"Swale-Trench Element Coefficients","phase":6,"archetype":"calculation","order_index":25,"description":"Computes coefficients for Mulden-Rigolen-Elemente per Anhang B.4."},{"code":"M104-26","title_de":"Aufteilungswerte Mulden-Rigolen-Systeme","title_en":"Swale-Trench System Coefficients","phase":6,"archetype":"calculation","order_index":26,"description":"Computes coefficients for Mulden-Rigolen-Systeme per Anhang B.5 (incl. Drosselabflussspende q_Dr)."},{"code":"M104-27","title_de":"Aufteilungswerte Niederschlagswassernutzung","title_en":"Rainwater Harvesting Coefficients","phase":6,"archetype":"calculation","order_index":27,"description":"Computes a_A, g_A (=0), v_A, e_A for rainwater nutzungs- oder Bewässerungsanlagen."},{"code":"M104-28","title_de":"Anlagenkoeffizienten — Zusammenfassung","title_en":"Facility Coefficient Summary","phase":6,"archetype":"summary","order_index":28,"description":"Consolidates facility-level coefficients (incl. fixed Tab. B.1 values)."},{"code":"M104-29","title_de":"Kombinierte Wasserbilanzberechnung","title_en":"Combined Water Balance Calculation","phase":7,"archetype":"calculation","order_index":29,"description":"Combines surface coefficients (M104-21) with facility coefficients (M104-28) for developed-state balance."},{"code":"M104-30","title_de":"Flächengewichtete Mittelwertbildung","title_en":"Area-Weighted Average Calculation","phase":7,"archetype":"calculation","order_index":30,"description":"Computes area-weighted averages of a, g, v for the entire balance area."},{"code":"M104-31","title_de":"Wasserbilanz bebauter Zustand","title_en":"Developed State Water Balance","phase":7,"archetype":"calculation","order_index":31,"description":"Final developed-state balance: R_D, GWN, ET_a [mm/a] and aufteilungswerte a, g, v."},{"code":"M104-32","title_de":"Wasserbilanz Referenzzustand & Nachweis","title_en":"Reference State Water Balance & Verification","phase":7,"archetype":"calculation","order_index":32,"description":"Final reference-state balance. Input to deviation analysis M104-33."},{"code":"M104-33","title_de":"Abweichungsanalyse","title_en":"Deviation Analysis","phase":7,"archetype":"verification","order_index":33,"description":"Compares bebauter vs unbebauter Zustand. Flags Abweichungen > 5-10 percentage points per §5.3.3."},{"code":"M104-34","title_de":"Hydrologisches Dreieck","title_en":"Hydrological Triangle","phase":7,"archetype":"verification","order_index":34,"description":"Plots both states in the hydrological triangle (Bild 2) for visual comparison."},{"code":"M104-35","title_de":"Finales Lieferdokument","title_en":"Final Deliverable","phase":7,"archetype":"verification","order_index":35,"description":"Complete project water balance documentation for submission to authority."}],"sections":[{"ws_code":"M104-01","code":"A","title_de":"Purpose and Context","order_index":1,"parent_code":null},{"ws_code":"M104-01","code":"B","title_de":"Input Parameters","order_index":2,"parent_code":null},{"ws_code":"M104-01","code":"C","title_de":"Worksheet-Specific Content","order_inde