p"},"clause_reference":"§3.3, §C.4.1","description":"Tree rotation age for BAGLUVA.","consumer_worksheets":["M104-20"]},{"ws_code":"M104-01","section_code":"E","symbol":"relevance_check_required","label_de":"800 m² Relevanzschwelle erfüllt?","label_en":"Relevance Threshold (800 m²) Met?","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"A_E_k_b >= 800"},"clause_reference":"§5.3.3","description":"True if A_E,k,b >= 800 m²; triggers full water balance per §5.3.3.","consumer_worksheets":["M104-02","M104-35"]},{"ws_code":"M104-21","section_code":"F","symbol":"balance_sum_check","label_de":"Kontrollbedingung a+g+v=1 erfüllt?","label_en":"Control Condition a+g+v=1 Verified?","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"|a+g+v-1| < tolerance"},"clause_reference":"§A.1, §B.1, §C.6 Hinweis","description":"Check aufteilungswerte sum to 1; otherwise apply correction factor 1/(a+g+v).","consumer_worksheets":["M104-21","M104-28","M104-31"]},{"ws_code":"M104-33","section_code":"F","symbol":"deviation_within_target","label_de":"Abweichung im Zielbereich (5-10 Pp)?","label_en":"Deviation Within Target (5-10 percentage points)?","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"|delta_a|, |delta_g|, |delta_v| <= 0.05-0.10"},"clause_reference":"§5.3.3","description":"Verifies developed-state aufteilungswerte differ from reference by <= 5-10 Pp.","consumer_worksheets":["M104-35"]},{"ws_code":"M104-01","section_code":"L","symbol":"worksheet_status","label_de":"Arbeitsblatt-Status","label_en":"Worksheet Status","data_type":"enum","unit":null,"is_required":true,"enum_values":[{"value":"draft","label_de":"Entwurf","label_en":"Draft","order_index":1,"regulation_reference":"workflow"},{"value":"submitted_for_review","label_de":"Zur Prüfung eingereicht","label_en":"Submitted for review","order_index":2,"regulation_reference":"workflow"},{"value":"in_review","label_de":"In Prüfung","label_en":"In review","order_index":3,"regulation_reference":"workflow"},{"value":"engineer_approved","label_de":"Ingenieur freigegeben","label_en":"Engineer approved","order_index":4,"regulation_reference":"workflow"},{"value":"sent_to_customer","label_de":"An Kunde gesendet","label_en":"Sent to customer","order_index":5,"regulation_reference":"workflow"},{"value":"customer_approved","label_de":"Kunde freigegeben","label_en":"Customer approved","order_index":6,"regulation_reference":"workflow"},{"value":"final","label_de":"Final","label_en":"Final","order_index":7,"regulation_reference":"workflow"}],"validation_rules":{"raw":"Enum_Values: worksheet_status"},"clause_reference":"engineer methodology","description":"Lifecycle status per worksheet.","consumer_worksheets":["all"]},{"ws_code":"M104-01","section_code":"L","symbol":"worksheet_signature_engineer","label_de":"Unterschrift Ingenieur","label_en":"Engineer Signature","data_type":"text","unit":null,"is_required":false,"enum_values":null,"validation_rules":null,"clause_reference":"engineer methodology","description":null,"consumer_worksheets":["all"]},{"ws_code":"M104-01","section_code":"L","symbol":"worksheet_signature_date","label_de":"Datum Freigabe","label_en":"Approval Date","data_type":"date","unit":null,"is_required":false,"enum_values":null,"validation_rules":null,"clause_reference":"engineer methodology","description":null,"consumer_worksheets":["all"]}],"equations":[{"ws_code":"M104-07","equation_number":"1","formula":"P_korr = R + ET_a","input_symbols":["P_korr","R","ET_a"],"output_symbol":"P_korr","clause_reference":"§5.1, Gl. (1) (line 530)","description":"Wasserhaushaltsgleichung"},{"ws_code":"M104-07","equation_number":"2","formula":"R = R_D + R_B","input_symbols":["R","R_D","R_B"],"output_symbol":"R","clause_reference":"§5.1, Gl. (2) (line 538)","description":"Aufteilung des Abflusses"},{"ws_code":"M104-07","equation_number":"3","formula":"R_D = R_D,o + R_D,z","input_symbols":["R_D","R_D_o","R_D_z"],"output_symbol":"R_D","clause_reference":"§5.1, Gl. (3) (line 539)","description":"Aufteilung des Direktabflusses"},{"ws_code":"M104-07","equation_number":"4","formula":"R_B = GWN","input_symbols":["R_B","GWN"],"output_symbol":"R_B","clause_reference":"§5.1, Gl. (4) (line 540)","description":"Basisabfluss gleich Grundwasserneubildung"},{"ws_code":"M104-07","equation_number":"5","formula":"R_D = R - GWN","input_symbols":["R","GWN","R_D"],"output_symbol":"R_D","clause_reference":"§5.1, Gl. (5) (line 548)","description":"Direktabfluss aus Differenz"},{"ws_code":"M104-07","equation_number":"6","formula":"P_korr = R_D + GWN + ET_a","input_symbols":["P_korr","R_D","GWN","ET_a"],"output_symbol":"P_korr","clause_reference":"§5.1, Gl. (6) (line 556); §5.3.2.2 (line 635)","description":"Vereinfachte Wasserbilanz"},{"ws_code":"M104-07","equation_number":"7","formula":"a = R_D / P_korr","input_symbols":["R_D","P_korr"],"output_symbol":"a","clause_reference":"§5.1 (lines 564-567); referenced as Gl. (7) in §5.2.5 (line 606), §C.2 (line 1093)","description":"Aufteilungswert für den Direktabfluss"},{"ws_code":"M104-07","equation_number":"8","formula":"g = GWN / P_korr","input_symbols":["GWN","P_korr"],"output_symbol":"g","clause_reference":"§5.1 (lines 564-567); referenced as Gl. (8) in §5.2.5, §C.2","description":"Aufteilungswert für die Grundwasserneubildung"},{"ws_code":"M104-07","equation_number":"9","formula":"v = ET_a / P_korr","input_symbols":["ET_a","P_korr"],"output_symbol":"v","clause_reference":"§5.1 (lines 564-567); referenced as Gl. (9) in §5.2.5, §C.2","description":"Aufteilungswert für die Verdunstung"},{"ws_code":"M104-21","equation_number":"10","formula":"P_korr = a_F * P_korr + g_F * P_korr + v_F * P_korr   [mm/a]","input_symbols":["a_F","g_F","v_F","P_korr"],"output_symbol":"P_korr","clause_reference":"§5.3.2.2, Gl. (10) (line 636)","description":"Wasserbilanz für Flächen"},{"ws_code":"M104-22","equation_number":"11","formula":"Z = a_F * P_korr   [mm/a]","input_symbols":["a_F","P_korr"],"output_symbol":"Z","clause_reference":"§5.3.2.3 (line 651); implied Gl. (11)","description":"Zufluss zur Bewirtschaftungsanlage"},{"ws_code":"M104-22","equation_number":"12","formula":"Z = a_A * Z + g_A * Z + v_A * Z   [mm/a]","input_symbols":["a_A","g_A","v_A","Z"],"output_symbol":"Z","clause_reference":"§5.3.2.3, Gl. (12) (line 652)","description":"Aufteilung des Anlagenzuflusses"},{"ws_code":"M104-20","equation_number":"C.1","formula":"ET_a,korr = ET_a * f_L * f_W","input_symbols":["ET_a","f_L","f_W"],"output_symbol":"ET_a_korr","clause_reference":"§C.4.2, Gl. (C.1) (line 1208)","description":"Korrigierte tatsächliche Verdunstung"},{"ws_code":"M104-20","equation_number":"C.2","formula":"a_F = sum_{i=1..n}(R_D,i * A_E,k,nb,i) / (P_korr * sum_{i=1..n}(A_E,k,nb,i))","input_symbols":["R_D_i","A_E_k_nb_i","P_korr"],"output_symbol":"a_F","clause_reference":"§C.6, Gl. (C.2) (line 1276)","description":"Aufteilungswert a_F für nicht befestigte Flächen"},{"ws_code":"M104-20","equation_number":"C.3","formula":"g_F = sum_{i=1..n}(GWN_i * A_E,k,nb,i) / (P_korr * sum_{i=1..n}(A_E,k,nb,i))","input_symbols":["GWN_i","A_E_k_nb_i","P_korr"],"output_symbol":"g_F","clause_reference":"§C.6, Gl. (C.3) (line 1277)","description":"Aufteilungswert g_F für nicht befestigte Flächen"},{"ws_code":"M104-20","equation_number":"C.4","formula":"v_F = sum_{i=1..n}(ET_a,i * A_E,k,nb,i) / (P_korr * sum_{i=1..n}(A_E,k,nb,i))","input_symbols":["ET_a_i","A_E_k_nb_i","P_korr"],"output_symbol":"v_F","clause_reference":"§C.6, Gl. (C.4) (line 1278)","description":"Aufteilungswert v_F für nicht befestigte Flächen"},{"ws_code":"M104-16","equation_number":"A.2","formula":"a_F = 0.9115 + 0.00007063*P - 0.000007498*ET_p - 0.2063*ln(Sp + 1)","input_symbols":["P","ET_p","Sp"],"output_symbol":"a_F","clause_reference":"§A.2 (line 765)","description":"Regressionsgleichung Steildächer / Flachdach glatt"},{"ws_code":"M104-16","equation_number":"A.3","formula":"a_F = 0.8658 + 0.0001659*P - 0.00009945*ET_p - 0.1542*ln(Sp + 1)","input_symbols":["P","ET_p","Sp"],"output_symbol":"a_F","clause_reference":"§A.3 (line 775)","description":"Regressionsgleichung Flachdach rau / Asphalt / Beton"},{"ws_code":"M104-19","equation_number":"A.4","formula":"a_F = -8.3518 - 0.2455*f_B - 0.1095*ln(h_S) - 0.05748/(WK_max - WP) - 0.4256*(WK_max - WP) + 1.781*ln(P) - 0.002133*P + 7.7488e-7*(P - ET_p)^2 - 0.0005051*ET_p","input_symbols":["f_B","h_S","WK_max","WP","P","ET_p"],"output_symbol":"a_F","clause_reference":"§A.4 (lines 788-790)","description":"Regressionsgleichung Gründächer"},{"ws_code":"M104-19","equation_number":"A.5","formula":"a_F = 0.9231 + 0.000254*P - 0.0003226*ET_p - 0.1472*ln(Sp + 1)","input_symbols":["P","ET_p","Sp"],"output_symbol":"a_F","clause_reference":"§A.5 (line 820)","description":"Regressionsgleichung Einstaudächer"},{"ws_code":"M104-18","equation_number":"A.6","formula":"a_F = 0.0800734*ln(P) - 0.0582828*f_Fu - 0.0501693*Sp - 0.385767*(WK_max - WP) + 8.7040284/(11.9086896 + k_f) ; g_F = -0.2006 - 0.000253*ET_p + 0.05615*f_Fu - 0.0636*ln(1 + Sp) + 0.1596*ln(1 + k_f) + 0.2778*(WK_max - WP) ; v_F = 0.8529 - 0.1248*ln(P) + 0.00005057*ET_p + 0.002372*f_Fu + 0.1583*ln(1 + Sp)","input_symbols":["P","ET_p","f_Fu","Sp","WK_max","WP","k_f"],"output_symbol":"a_F, g_F, v_F","clause_reference":"§A.6 (lines 830-834)","description":"Regressionsgleichungen teildurchlässige Beläge 2-5%"},{"ws_code":"M104-18","equation_number":"A.7","formula":"a_F = 0.05912*ln(P) - 0.02749*f_Fu - 0.03671*Sp - 0.30514*(WK_max - WP) + 4.97687/(4.7975 + k_f) ; g_F = 0.00004941*P - 0.0002817*ET_p + 0.02566*f_Fu - 0.03823*Sp + 0.691*exp(-6.465/k_f) ; v_F = 0.9012 - 0.1325*ln(P) + 0.00006661*ET_p + 0.002302*f_Fu + 0.1489*ln(1 + Sp)","input_symbols":["P","ET_p","f_Fu","Sp","WK_max","WP","k_f"],"output_symbol":"a_F, g_F, v_F","clause_reference":"§A.7 (lines 848-850)","description":"Regressionsgleichungen teildurchlässige Beläge 6-10%"},{"ws_code":"M104-18","equation_number":"A.8","formula":"a_F = 0.000001969*P - 0.005116*ln(Sp) - 0.0001051*h_D + 0.01753*exp(4.576/k_f) ; g_F = 0.2468883*ln(P) - 0.0003938*ET_p + 0.0017083*Sp - 0.0015998*h_D - 0.6703502*exp(0.1122885/k_f) ; v_F = 0.2111 - 0.2544*ln(P) + 0.2073*ln(ET_p) + 0.0006249*Sp + 0.123*ln(h_D) - 0.000002806*k_f","input_symbols":["P","ET_p","Sp","h_D","k_f"],"output_symbol":"a_F, g_F, v_F","clause_reference":"§A.8 (lines 862-864)","description":"Regressionsgleichungen Porensteine / Schotterrasen / Kies"},{"ws_code":"M104-18","equation_number":"A.9","formula":"a_F = 0.145704 - 0.059177*ln(f_Fu) - 0.007354*Sp - 0.050531*ln(WK_max - WP) ; g_F = -0.02927 + 0.1483*ln(P) - 0.000269*ET_p - 0.09913*ln(1 + Sp) + 0.05222*(WK_max - WP) ; v_F = 1.106 - 0.1625*ln(P) + 0.0001282*ET_p + 0.1131*ln(1 + Sp) + 0.2848*(WK_max - WP)","input_symbols":["P","ET_p","f_Fu","Sp","WK_max","WP"],"output_symbol":"a_F, g_F, v_F","clause_reference":"§A.9 (lines 875-877)","description":"Regressionsgleichungen Rasengittersteine"},{"ws_code":"M104-18","equation_number":"A.10","formula":"a_F = 0.00004517*P - 0.03454*ln(Sp) + 0.1958/(0.2873 + k_f) ; g_F = 0.19761*ln(P) - 0.000506*ET_p + 0.016372*Sp - 0.001618*h_D - 0.327742*exp(0.346808/k_f) ; v_F = 0.2111 - 0.2544*ln(P) + 0.2073*ln(ET_p) + 0.0006249*Sp + 0.123*ln(h_D) - 0.000002806*k_f","input_symbols":["P","ET_p","Sp","h_D","k_f"],"output_symbol":"a_F, g_F, v_F","clause_reference":"§A.10 (lines 888-890)","description":"Regressionsgleichungen wassergebundene Decke"},{"ws_code":"M104-23","equation_number":"B.2","formula":"a_A = 0.004264 + 0.001121*ln(P) - 0.002757*ln(f_S,F) ; g_A = 0.6207904 + 0.0899322*ln(P) - 0.0001152*ET_p - 0.0719723*ln(f_S,F) ; v_A = 0.3999 - 0.09317*ln(P) + 0.00009746*ET_p + 0.07474*ln(f_S,F)","input_symbols":["P","ET_p","f_S_F"],"output_symbol":"a_A, g_A, v_A","clause_reference":"§B.2 (lines 942-944)","description":"Regressionsgleichungen Flächenversickerung"},{"ws_code":"M104-24","equation_number":"B.3","formula":"a_A = 1 - g_A - v_A ; g_A = 0.8608 + 0.02385*ln(P) - 0.00005331*ET_p - 0.002827*f_S,M - 0.000002493*k_f + 0.0009514*ln(k_f / f_S,M) ; v_A = 0.000008562*ET_p + 2.611/(-64.35 + P) * f_S,M^0.9425 - 0.000001211*k_f","input_symbols":["P","ET_p","f_S_M","k_f"],"output_symbol":"a_A (=1-g-v), g_A, v_A","clause_reference":"§B.3 (lines 957-960)","description":"Regressionsgleichungen Versickerungsmulden"},{"ws_code":"M104-25","equation_number":"B.4","formula":"a_A = -0.03867 + 0.007684*ln(P) + 0.000003201*f_S,M + 0.0002564*k_f - 0.0001187*f_S,M*k_f + 0.004161*ln(k_f / f_S,M) ; g_A = 0.8803 + 0.01866*ln(P) - 0.00004867*ET_p - 0.001997*f_S,M + 0.0002365*k_f ; v_A = 0.000008879*ET_p + 2.528/(-81.65 + P) * f_S,M^0.9496 - 0.00007768*k_f","input_symbols":["P","ET_p","f_S_M","k_f"],"output_symbol":"a_A, g_A, v_A","clause_reference":"§B.4 (lines 975-978)","description":"Regressionsgleichungen Mulden-Rigolen-Elemente"},{"ws_code":"M104-26","equation_number":"B.5","formula":"a_A = 0.8112 + 0.0003473*P - 0.00001845*ET_p - 0.04793*f_S,M + 0.0007481*q_Dr - 0.4389*ln(k_f + 1) ; g_A = 1.669 - 0.3005*ln(P) - 0.00006933*ET_p + 0.3044*ln(f_S,M) + 0.4581*ln(k_f + 1) ; v_A = 0.1428 - 0.02661*ln(P) + 0.00005668*ET_p + 0.0288*ln(f_S,M) - 0.0001825*q_Dr - 0.01823*ln(k_f + 1)","input_symbols":["P","ET_p","f_S_M","q_Dr","k_f"],"output_symbol":"a_A, g_A, v_A","clause_reference":"§B.5 (lines 993-996)","description":"Regressionsgleichungen Mulden-Rigolen-Systeme"},{"ws_code":"M104-27","equation_number":"B.6","formula":"g_A = 0 ; a_A = 1 - v_A - e_A ; v_A = if(h_Bw == 0, 0, -0.0001927*P + 0.0001831*ET_p + 0.0006083*h_Bw - 0.0000003127*h_Bw^2 - 0.3092*exp(3.269/h_Sp) + 1.424/(2.782 + h_Br) + 0.0001885*h_Nu) ; e_A = if(h_Br == 0, 0, 0.4451 - 0.0003529*P - 0.00007728*ET_p + 0.06821*log10(h_Sp) - 0.0002507*h_Bw + 0.2349*log10(h_Br) + 0.0001738*h_Nu)","input_symbols":["P","ET_p","h_Sp","h_Br","h_Bw","h_Nu"],"output_symbol":"v_A, e_A; a_A=1-v_A-e_A; g_A=0","clause_reference":"§B.6 (lines 1013, 1024-1025, 1037-1038)","description":"Regressionsgleichungen Niederschlagswassernutzung"},{"ws_code":"M104-28","equation_number":"B.7","formula":"v_A = (ET_p * A_W) / (P * (A_W + sum_{i=1..n}(A_b,a,i * a_F,i))) ; a_A = 1 - v_A ; g_A = 0 ; check: 0 < v_A < 1 AND 0 < a_A < 1","input_symbols":["ET_p","A_W","P","A_b_a_i","a_F_i"],"output_symbol":"v_A; a_A = 1 - v_A","clause_reference":"§B.7 (lines 1054-1056)","description":"Regressionsgleichung Wasserfläche mit Dauerstau"}],"compliance":[{"ws_code":"M104-01","code":"REQ-01","title_de":"Anwendungsbereich (§1)","condition":"project_type IN {Neuerschließung, Konversion, Sanierung, Nachverdichtung}","description":"Project is within Anwendungsbereich of DWA-M 102-4: Wasserhaushaltsbilanz for stormwater management at planning stage.","clause_reference":"§1 Anwendungsbereich"},{"ws_code":"M104-01","code":"REQ-02","title_de":"Verweisungen (§2)","condition":"engineer_review","description":"Cross-referenced standards (DWA-A 102-1, DWA-A 102-2, DWA-A 138, DIN 1986-100) considered where relevant.","clause_reference":"§2 Verweisungen"},{"ws_code":"M104-01","code":"REQ-03","title_de":"800 m² Relevanzschwelle (§5.3.3)","condition":"A_E_k_b >= 800","description":"Full water balance required if A_E,k,b >= 800 m² (Relevanzgrenze analog DIN 1986-100).","clause_reference":"§5.3.3"},{"ws_code":"M104-07","code":"REQ-04","title_de":"Referenzzustand (§5.2)","condition":"all referenced fields present","description":"Reference (unbebauter) state water balance computed using WaSiG / Wasserhaushaltsmodell / GWneu / HAD.","clause_reference":"§5.2"},{"ws_code":"M104-07","code":"REQ-05","title_de":"Wasserhaushaltsgleichung Gl. (1) erfüllt","condition":"abs(P_korr - (R + ET_a)) <= tol","description":"Verify P_korr = R + ET_a holds within tolerance for reference state.","clause_reference":"§5.1, Gl. (1)"},{"ws_code":"M104-29","code":"REQ-06","title_de":"Bilanzgleichung Gl. (6) erfüllt","condition":"abs(P_korr - (R_D + GWN + ET_a)) <= tol","description":"Verify P_korr = R_D + GWN + ET_a holds for both reference and developed states.","clause_reference":"§5.1, §5.3.2.2, Gl. (6)"},{"ws_code":"M104-29","code":"REQ-07","title_de":"Kontrollbedingung Aufteilungswerte (a+g+v=1)","condition":"abs(a + g + v - 1) <= tol","description":"Verify a + g + v = 1 (or apply correction factor 1/(a+g+v) per §A.1).","clause_reference":"§A.1, §B.1, §C.6 Hinweis zur Korrektur von Bilanzfehlern"},{"ws_code":"M104-04","code":"REQ-08","title_de":"Gültigkeitsbereich P [500-1700 mm/a]","condition":"500 <= P <= 1700","description":"Mean annual precipitation P within validity range for Anhang A and B regression equations.","clause_reference":"§A.1, §B.1"},{"ws_code":"M104-04","code":"REQ-09","title_de":"Gültigkeitsbereich ET_p [450-700 mm/a]","condition":"450 <= ET_p <= 700","description":"Mean annual potential ET within validity range for Anhang A and B regression equations.","clause_reference":"§A.1, §B.1"},{"ws_code":"M104-16","code":"REQ-10","title_de":"Aufteilungswerte für Flächen (Anhang A)","condition":"abs(a_F + g_F + v_F - 1) <= tol per surface","description":"For every impervious surface, a_F + g_F + v_F = 1 via Anhang A.2-A.10.","clause_reference":"Tab. A.1, §A.2-A.10"},{"ws_code":"M104-22","code":"REQ-11","title_de":"Aufteilungswerte für Anlagen (Anhang B)","condition":"abs(a_A + g_A + v_A + e_A - 1) <= tol per facility","description":"For every facility, a_A + g_A + v_A = 1 (or +e_A for Niederschlagswassernutzung).","clause_reference":"Tab. B.1, §B.2-B.7"},{"ws_code":"M104-16","code":"REQ-12","title_de":"Negativwert-Behandlung (Anhang A.1, B.1)","condition":"no coefficient < 0; if had been, correction applied","description":"If a residual coefficient becomes negative, set to 0 and adjust others proportionally.","clause_reference":"§A.1, §B.1 Hinweis"},{"ws_code":"M104-22","code":"REQ-13","title_de":"Anhang B.7 Plausibilitätsprüfung (offene Wasserfläche)","condition":"(0 < v_A < 1) AND (0 < a_A < 1) for offene Wasserfläche","description":"For open water with permanent storage: 0 < v_A < 1 AND 0 < a_A < 1.","clause_reference":"§B.7 (line 1058)"},{"ws_code":"M104-07","code":"REQ-14","title_de":"Vegetationsflächen-Ansatz gewählt (§5.3.2.2)","condition":"consistent method choice","description":"For Vegetationsflächen: either Referenzzustand-Werte or Anhang C method, not mixed.","clause_reference":"§5.3.2.2 (line 641)"},{"ws_code":"M104-07","code":"REQ-15","title_de":"ET_a/ET_p Verhältniswert aus Tab. C.3","condition":"lookup in Tab. C.3 valid","description":"ET_a/ET_p ratio obtained from Tab. C.3 by lookup.","clause_reference":"Tab. C.3, §C.3"},{"ws_code":"M104-07","code":"REQ-16","title_de":"r-Wert aus Tab. C.7 (Anhang C.5)","condition":"valid lookup","description":"Direct-runoff ratio r from Tab. C.7 by (landuse, slope, soil, GW depth).","clause_reference":"Tab. C.7, §C.5"},{"ws_code":"M104-29","code":"REQ-17","title_de":"Vergleich bebauter vs unbebauter Zustand (§5.3.3)","condition":"max(|delta_a|,|delta_g|,|delta_v|) <= 0.10 (or fully justified)","description":"Compare developed-state a, g, v to reference-state. Target deviation <= 5-10 Prozentpunkte.","clause_reference":"§5.3.3 (line 662)"},{"ws_code":"M104-01","code":"REQ-18","title_de":"Bilanzgebiet definiert (§5.3.1)","condition":"A_E_k_b + A_E_k_nb == A_E_k","description":"Bilanzgebiet (A_E,k) clearly defined; A_E,k,b + A_E,k,nb = A_E,k.","clause_reference":"§5.3.1"},{"ws_code":"M104-29","code":"REQ-19","title_de":"Klimakennung dokumentiert (§6)","condition":"engineer_acknowledgment","description":"DWA Klimakennung values (KS2 Klimaschutz / KA2 Klimaanpassung) acknowledged.","clause_reference":"§6, Tab. 5, Tab. 6"},{"ws_code":"M104-01","code":"REQ-20","title_de":"Maßnahmen gewählt und gesichert (§4.3)","condition":"engineer_attestation","description":"Appropriate Bewirtschaftungsmaßnahmen chosen and legally secured.","clause_reference":"§4.3, §5.3.3 (line 660)"},{"ws_code":"M104-22","code":"REQ-21","title_de":"Niederschlagswasser-Nutzung Spezialfall (§B.6)","condition":"sum < 1 allowed when e_A > 0 per §B.6","description":"For Niederschlagswassernutzung: a_A + g_A + v_A < 1 IF e_A > 0 AND no Trinkwasser-Ersatz claimed locally.","clause_reference":"§B.6 (line 1014)"},{"ws_code":"M104-29","code":"REQ-22","title_de":"Approval workflow per worksheet","condition":"status IN {final, engineer_approved, customer_approved}","description":"Every worksheet has Status = Final or Approved with engineer signature and date.","clause_reference":"engineer methodology"}]}$p3c_json$::jsonb;
  v_std uuid;
BEGIN
  -- 1. standard (UPSERT by code)
  INSERT INTO standards (code, title_de, title_en, version)
  SELECT v_data->'standard'->>'code', v_data->'standard'->>'title_de',
         v_data->'standard'->>'title_en', v_data->'standard'->>'version'
  ON CONFLICT (code) DO UPDATE
    SET title_de = excluded.title_de, title_en = excluded.title_en, version = excluded.version;
  SELECT id INTO v_std FROM standards WHERE code = v_data->'standard'->>'code';

  -- 2. worksheet templates (UPSERT by standard_id+code)
  INSERT INTO worksheet_templates (standard_id, code, title_de, title_en, phase, archetype, order_index, description)
  SELECT v_std, w->>'code', w->>'title_de', w->>'title_en',
         (w->>'phase')::int, w->>'archetype', (w->>'order_index')::int, w->>'description'
  FROM jsonb_array_elements(v_data->'worksheets') AS w
  ON CONFLICT (standard_id, code) DO UPDATE
    SET title_de = excluded.title_de, title_en = excluded.title_en, phase = excluded.phase,
        archetype = excluded.archetype, order_index = excluded.order_index, description = excluded.description;

  -- 3. sections: null fields.section_id, wipe + reinsert (no unique constraint on code), resolve parents
  UPDATE fields SET section_id = NULL
   WHERE worksheet_template_id IN (SELECT id FROM worksheet_templates WHERE standard_id = v_std);
  DELETE FROM worksheet_sections
   WHERE worksheet_template_id IN (SELECT id FROM worksheet_templates WHERE standard_id = v_std);

  INSERT INTO worksheet_sections (worksheet_template_id, code, title_de, order_index)
  SELECT wt.id, s->>'code', s->>'title_de', (s->>'order_index')::int
  FROM jsonb_array_elements(v_data->'sections') AS s
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = s->>'ws_code';

  UPDATE worksheet_sections AS child
     SET parent_section_id = parent.id
  FROM jsonb_array_elements(v_data->'sections') AS s
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = s->>'ws_code'
  JOIN worksheet_sections parent ON parent.worksheet_template_id = wt.id AND parent.code = s->>'parent_code'
  WHERE s->>'parent_code' IS NOT NULL
    AND child.worksheet_template_id = wt.id
    AND child.code = s->>'code';

  -- 4. fields (UPSERT by worksheet_template_id+symbol; verification_status NOT touched)
  INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit,
                      is_required, enum_values, validation_rules, clause_reference, description, consumer_worksheets)
  SELECT wt.id,
         (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = wt.id AND ws.code = f->>'section_code' LIMIT 1),
         f->>'symbol', f->>'label_de', f->>'label_en', f->>'data_type', f->>'unit',
         (f->>'is_required')::boolean,
         CASE WHEN jsonb_typeof(f->'enum_values') = 'array' THEN f->'enum_values' ELSE NULL END,
         CASE WHEN jsonb_typeof(f->'validation_rules') = 'object' THEN f->'validation_rules' ELSE NULL END,
         f->>'clause_reference', f->>'description',
         CASE WHEN jsonb_typeof(f->'consumer_worksheets') = 'array'
              THEN ARRAY(SELECT jsonb_array_elements_text(f->'consumer_worksheets')) ELSE NULL END
  FROM jsonb_array_elements(v_data->'fields') AS f
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = f->>'ws_code'
  ON CONFLICT (worksheet_template_id, symbol) DO UPDATE
    SET section_id = excluded.section_id, label_de = excluded.label_de, label_en = excluded.label_en,
        data_type = excluded.data_type, unit = excluded.unit, is_required = excluded.is_required,
        enum_values = excluded.enum_values, validation_rules = excluded.validation_rules,
        clause_reference = excluded.clause_reference, description = excluded.description,
        consumer_worksheets = excluded.consumer_worksheets;

  -- 5. equations (UPSERT by worksheet_template_id+equation_number; verification_status preserved)
  INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, clause_reference, description)
  SELECT wt.id, e->>'equation_number', e->>'formula',
         CASE WHEN jsonb_typeof(e->'input_symbols') = 'array' THEN ARRAY(SELECT jsonb_array_elements_text(e->'input_symbols')) ELSE NULL END,
         e->>'output_symbol', e->>'clause_reference', e->>'description'
  FROM jsonb_array_elements(v_data->'equations') AS e
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = e->>'ws_code'
  ON CONFLICT (worksheet_template_id, equation_number) DO UPDATE
    SET formula = excluded.formula, input_symbols = excluded.input_symbols, output_symbol = excluded.output_symbol,
        clause_reference = excluded.clause_reference, description = excluded.description;

  -- 6. compliance requirements (UPSERT by worksheet_template_id+code)
  INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, condition, description, clause_reference, severity)
  SELECT wt.id, c->>'code', c->>'title_de', c->>'condition', c->>'description', c->>'clause_reference', 'block'
  FROM jsonb_array_elements(v_data->'compliance') AS c
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = c->>'ws_code'
  ON CONFLICT (worksheet_template_id, code) DO UPDATE
    SET title_de = excluded.title_de, condition = excluded.condition, description = excluded.description,
        clause_reference = excluded.clause_reference, severity = excluded.severity;
END
$p3c_do$;
